INSERT INTO public.properties (reference_id, title, description, property_type, transaction_type, price, bedrooms, bathrooms, area_sqft, location_lat, location_lng, address_full, community, sub_community, building_name, floor_number, is_furnished, amenities, images, status, featured, verified, agent_id, searchable_content) VALUES
('DXB-001', 'Ultra-Luxury Penthouse | Burj Khalifa View', 'Experience the pinnacle of luxury living in this stunning 4-bedroom penthouse with panoramic views of the Burj Khalifa and Dubai Fountain. Features include a private elevator, rooftop terrace, and premium finishes throughout.', 'penthouse', 'sale', 18500000, 4, 5, 4800, 25.1972, 55.2744, 'Downtown Boulevard, Downtown Dubai', 'Downtown Dubai', 'Boulevard Point', 'The Residences', 45, true, '["Private Elevator", "Rooftop Terrace", "Smart Home", "Concierge", "Gym", "Pool", "Spa", "Valet Parking"]'::jsonb, '[{"url": "https://images.unsplash.com/photo-1512917774080-9991f1c4c750?w=800", "caption": "Living Room", "is_primary": true}, {"url": "https://images.unsplash.com/photo-1545324418-cc1a3fa10c00?w=800", "caption": "Master Bedroom", "is_primary": false}, {"url": "https://images.unsplash.com/photo-1512918760532-3ed4659b28d5?w=800", "caption": "Kitchen", "is_primary": false}]'::jsonb, 'active', true, true, '22222222-2222-2222-2222-222222222222', to_tsvector('english', 'penthouse downtown dubai burj khalifa luxury view')),
('DXB-002', 'Stunning Villa | Palm Jumeirah | Private Beach', 'Magnificent 6-bedroom signature villa on the prestigious Palm Jumeirah frond. Direct beach access, private pool, and breathtaking Arabian Gulf views. Perfect for families seeking ultimate privacy and luxury.', 'villa', 'sale', 35000000, 6, 7, 8500, 25.1124, 55.1390, 'Frond M, Palm Jumeirah', 'Palm Jumeirah', 'Frond M', 'Signature Villa', 0, true, '["Private Beach", "Private Pool", "Maid''s Room", "Driver''s Room", "Smart Home", "Landscaped Garden", "BBQ Area", "Home Cinema"]'::jsonb, '[{"url": "https://images.unsplash.com/photo-1613490493576-7fde63acd811?w=800", "caption": "Exterior", "is_primary": true}, {"url": "https://images.unsplash.com/photo-1613545325278-f24b0cae1224?w=800", "caption": "Living Area", "is_primary": false}]'::jsonb, 'active', true, true, '33333333-3333-3333-3333-333333333333', to_tsvector('english', 'villa palm jumeirah beach private luxury family')),
('DXB-003', 'Modern Townhouse | Arabian Ranches | Golf Course', 'Beautiful 4-bedroom townhouse overlooking the championship golf course at Arabian Ranches. Spacious layout, upgraded kitchen, and access to world-class community amenities.', 'townhouse', 'sale', 4200000, 4, 5, 3200, 25.0545, 55.2708, 'Arabian Ranches, Dubai', 'Arabian Ranches', 'Savannah', 'Maple', 0, false, '["Golf Course View", "Community Pool", "Kids Play Area", "Tennis Court", "Cycling Track", "Retail Center", "School Nearby"]'::jsonb, '[{"url": "https://images.unsplash.com/photo-1564013799919-ab600027ffc6?w=800", "caption": "Front View", "is_primary": true}]'::jsonb, 'active', false, true, '22222222-2222-2222-2222-222222222222', to_tsvector('english', 'townhouse arabian ranches golf course family community')),
('DXB-004', 'Luxury Apartment | Dubai Marina | Full Marina View', 'Spacious 3-bedroom apartment in the heart of Dubai Marina with stunning full marina views. Walking distance to JBR Beach, Marina Walk, and Dubai Metro.', 'apartment', 'sale', 3800000, 3, 4, 2100, 25.0804, 55.1396, 'Dubai Marina, Dubai', 'Dubai Marina', 'Marina Promenade', 'Elite Residence', 28, true, '["Marina View", "Balcony", "Gym", "Infinity Pool", "24/7 Security", "Covered Parking", "Metro Nearby"]'::jsonb, '[{"url": "https://images.unsplash.com/photo-1522708323590-d24dbb6b0267?w=800", "caption": "Living Room", "is_primary": true}]'::jsonb, 'active', true, true, '22222222-2222-2222-2222-222222222222', to_tsvector('english', 'apartment dubai marina view investment rental')),
('DXB-005', 'Exclusive Penthouse | Business Bay | Canal View', 'Rare opportunity to own this exclusive 5-bedroom penthouse with direct Dubai Water Canal views. Premium tower with 5-star amenities and proximity to Downtown Dubai.', 'penthouse', 'sale', 22000000, 5, 6, 5500, 25.1867, 55.2633, 'Business Bay, Dubai', 'Business Bay', 'Bay Square', 'Canal Tower', 52, true, '["Canal View", "Private Pool", "Jacuzzi", "Smart Home", "Concierge", "Spa", "Fine Dining", "Helipad Access"]'::jsonb, '[{"url": "https://images.unsplash.com/photo-1502672260266-1c1ef2d93688?w=800", "caption": "Panoramic View", "is_primary": true}]'::jsonb, 'active', true, true, '33333333-3333-3333-3333-333333333333', to_tsvector('english', 'penthouse business bay canal luxury exclusive'));
INSERT INTO public.properties (reference_id, title, description, property_type, transaction_type, price, bedrooms, bathrooms, area_sqft, location_lat, location_lng, community, building_name, is_furnished, amenities, images, status, verified, agent_id, searchable_content) VALUES
('DXB-R01', 'Fully Furnished Studio | JLT | Metro Access', 'Cozy fully furnished studio in Jumeirah Lake Towers with easy access to DMCC Metro Station. Perfect for young professionals.', 'apartment', 'rent', 65000, 0, 1, 550, 25.0693, 55.1423, 'Jumeirah Lake Towers', 'Lake Level', true, '["Furnished", "Gym", "Pool", "Metro Nearby", "Supermarket", "Restaurants"]'::jsonb, '[{"url": "https://images.unsplash.com/photo-1536376379240-8699e4203a8e?w=800", "caption": "Studio", "is_primary": true}]'::jsonb, 'active', true, '22222222-2222-2222-2222-222222222222', to_tsvector('english', 'studio jlt furnished rental metro affordable')),
('DXB-R02', 'Spacious 2BR | Dubai Hills Estate | Park View', 'Beautiful 2-bedroom apartment in Dubai Hills Estate with serene park views. Family-friendly community with top schools nearby.', 'apartment', 'rent', 140000, 2, 3, 1400, 25.1053, 55.2453, 'Dubai Hills Estate', 'Parkways', false, '["Park View", "Balcony", "Gym", "Pool", "Kids Play Area", "Schools Nearby", "Mall Nearby"]'::jsonb, '[{"url": "https://images.unsplash.com/photo-1502005229762-cf1b2da7c5d6?w=800", "caption": "Living Area", "is_primary": true}]'::jsonb, 'active', true, '33333333-3333-3333-3333-333333333333', to_tsvector('english', 'apartment dubai hills park family rental schools'));
INSERT INTO public.projects (name, developer_id, description, location_lat, location_lng, community, completion_date, total_units, units_sold, starting_price, images, brochure_url, floor_plans, amenities, payment_plan, status) VALUES
('Emaar Beachfront', '11111111-1111-1111-1111-111111111111', 'Exclusive beachfront living on a man-made island adjacent to Palm Jumeirah. A collection of luxury residences with private beach access and stunning sea views.', 25.1050, 55.1280, 'The Palm Jumeirah', '2027-12-31', 250, 180, 2500000, '[{"url": "https://images.unsplash.com/photo-1545324418-cc1a3fa10c00?w=800", "caption": "Project Render"}]'::jsonb, 'https://example.com/brochure.pdf', '[{"type": "1BR", "area": 850}, {"type": "2BR", "area": 1400}, {"type": "3BR", "area": 2100}]'::jsonb, '["Private Beach", "Infinity Pool", "Beach Club", "Retail Outlets", "Restaurants", "Gym", "Spa", "Kids Zone"]'::jsonb, '{"down_payment": 10, "during_construction": 60, "on_handover": 30}'::jsonb, 'active'),
('Dubai Creek Harbour', '11111111-1111-1111-1111-111111111111', 'A waterfront city within a city, offering stunning views of the Dubai Creek and the iconic Dubai Creek Tower. Modern apartments with world-class amenities.', 25.2285, 55.3273, 'Dubai Creek Harbour', '2026-06-30', 500, 320, 1800000, '[{"url": "https://images.unsplash.com/photo-1486406146926-c692060303df?w=800", "caption": "Tower View"}]'::jsonb, 'https://example.com/creek-brochure.pdf', '[{"type": "Studio", "area": 500}, {"type": "1BR", "area": 800}, {"type": "2BR", "area": 1300}]'::jsonb, '["Creek View", "Marina", "Retail Mall", "Parks", "Walking Trails", "Gym", "Pool", "Children Play Area"]'::jsonb, '{"down_payment": 5, "during_construction": 70, "on_handover": 25}'::jsonb, 'active'),
('MBR City District One', '11111111-1111-1111-1111-111111111111', 'An extravagant community featuring luxury villas and estates surrounding a crystal lagoon. Inspired by Mediterranean architecture with lush green landscapes.', 25.1643, 55.2978, 'Mohammed Bin Rashid City', '2028-03-31', 150, 95, 8500000, '[{"url": "https://images.unsplash.com/photo-1600596542815-ffad4c1539a9?w=800", "caption": "Villa Community"}]'::jsonb, 'https://example.com/mbr-brochure.pdf', '[{"type": "4BR Villa", "area": 4500}, {"type": "5BR Villa", "area": 6000}, {"type": "6BR Mansion", "area": 9000}]'::jsonb, '["Crystal Lagoon", "Private Beach", "Green Parks", "Cycling Tracks", "Equestrian Center", "International Schools", "Healthcare", "Retail"]'::jsonb, '{"down_payment": 20, "during_construction": 50, "on_handover": 30}'::jsonb, 'launching');
